Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
powerpc/sstep: Fix darn emulation

Commit 8813ff49607e ("powerpc/sstep: Check instruction validity
against ISA version before emulation") introduced a proper way to skip
unknown instructions. This makes sure that the same is used for the
darn instruction when the range selection bits have a reserved value.

Fixes: a23987ef267a ("powerpc: sstep: Add support for darn instruction")
Signed-off-by: Sandipan Das <sandipan@linux.ibm.com>
Signed-off-by: Michael Ellerman <mpe@ellerman.id.au>
Link: https://lore.kernel.org/r/20210204080744.135785-2-sandipan@linux.ibm.com

Here is the root cause:
The bug was caused by the improper handling of the "darn" instruction when the range selection bits had a reserved value. Instead of redirecting to a proper error handling mechanism, the code returned -1, which did not align with the intended behavior of skipping unknown instructions based on the ISA version. This inconsistency could lead to incorrect emulation of the instruction.

Here is the patch:
  */
 int analyse_instr(struct instruction_op *op, const struct pt_regs *regs,
 		  struct ppc_inst instr)
 {
 #ifdef CONFIG_PPC64
 	unsigned int suffixopcode, prefixtype, prefix_r;
 #endif
 	unsigned int opcode, ra, rb, rc, rd, spr, u;
 	unsigned long int imm;
 	unsigned long int val, val2;
 	unsigned int mb, me, sh;
 	unsigned int word, suffix;
 	long ival;

 	word = ppc_inst_val(instr);
 	suffix = ppc_inst_suffix(instr);

 	op->type = COMPUTE;

 	opcode = ppc_inst_primary_opcode(instr);
 	switch (opcode) {
 	case 16:	/* bc */
 		op->type = BRANCH;
 		imm = (signed short)(word & 0xfffc);
 		if ((word & 2) == 0)
 			imm += regs->nip;
 		op->val = truncate_if_32bit(regs->msr, imm);
 		if (word & 1)
 			op->type |= SETLK;
 		if (branch_taken(word, regs, op))
 			op->type |= BRTAKEN;
 		return 1;
 #ifdef CONFIG_PPC64
 	case 17:	/* sc */
 		if ((word & 0xfe2) == 2)
 			op->type = SYSCALL;
 		else if (IS_ENABLED(CONFIG_PPC_BOOK3S_64) &&
 				(word & 0xfe3) == 1) {	/* scv */
 			op->type = SYSCALL_VECTORED_0;
 			if (!cpu_has_feature(CPU_FTR_ARCH_300))
 				goto unknown_opcode;
 		} else
 			op->type = UNKNOWN;
 		return 0;
 #endif
 	case 18:	/* b */
 		op->type = BRANCH | BRTAKEN;
 		imm = word & 0x03fffffc;
 		if (imm & 0x02000000)
 			imm -= 0x04000000;
 		if ((word & 2) == 0)
 			imm += regs->nip;
 		op->val = truncate_if_32bit(regs->msr, imm);
 		if (word & 1)
 			op->type |= SETLK;
 		return 1;
 	case 19:
 		switch ((word >> 1) & 0x3ff) {
 		case 0:		/* mcrf */
 			op->type = COMPUTE + SETCC;
 			rd = 7 - ((word >> 23) & 0x7);
 			ra = 7 - ((word >> 18) & 0x7);
 			rd *= 4;
 			ra *= 4;
 			val = (regs->ccr >> ra) & 0xf;
 			op->ccval = (regs->ccr & ~(0xfUL << rd)) | (val << rd);
 			return 1;

 		case 16:	/* bclr */
 		case 528:	/* bcctr */
 			op->type = BRANCH;
 			imm = (word & 0x400)? regs->ctr: regs->link;
 			op->val = truncate_if_32bit(regs->msr, imm);
 			if (word & 1)
 				op->type |= SETLK;
 			if (branch_taken(word, regs, op))
 				op->type |= BRTAKEN;
 			return 1;

 		case 18:	/* rfid, scary */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = RFI;
 			return 0;

 		case 150:	/* isync */
 			op->type = BARRIER | BARRIER_ISYNC;
 			return 1;

 		case 33:	/* crnor */
 		case 129:	/* crandc */
 		case 193:	/* crxor */
 		case 225:	/* crnand */
 		case 257:	/* crand */
 		case 289:	/* creqv */
 		case 417:	/* crorc */
 		case 449:	/* cror */
 			op->type = COMPUTE + SETCC;
 			ra = (word >> 16) & 0x1f;
 			rb = (word >> 11) & 0x1f;
 			rd = (word >> 21) & 0x1f;
 			ra = (regs->ccr >> (31 - ra)) & 1;
 			rb = (regs->ccr >> (31 - rb)) & 1;
 			val = (word >> (6 + ra * 2 + rb)) & 1;
 			op->ccval = (regs->ccr & ~(1UL << (31 - rd))) |
 				(val << (31 - rd));
 			return 1;
 		}
 		break;
 	case 31:
 		switch ((word >> 1) & 0x3ff) {
 		case 598:	/* sync */
 			op->type = BARRIER + BARRIER_SYNC;
 #ifdef __powerpc64__
 			switch ((word >> 21) & 3) {
 			case 1:		/* lwsync */
 				op->type = BARRIER + BARRIER_LWSYNC;
 				break;
 			case 2:		/* ptesync */
 				op->type = BARRIER + BARRIER_PTESYNC;
 				break;
 			}
 #endif
 			return 1;

 		case 854:	/* eieio */
 			op->type = BARRIER + BARRIER_EIEIO;
 			return 1;
 		}
 		break;
 	}

 	/* Following cases refer to regs->gpr[], so we need all regs */
 	if (!FULL_REGS(regs))
 		return -1;

 	rd = (word >> 21) & 0x1f;
 	ra = (word >> 16) & 0x1f;
 	rb = (word >> 11) & 0x1f;
 	rc = (word >> 6) & 0x1f;

 	switch (opcode) {
 #ifdef __powerpc64__
 	case 1:
 		if (!cpu_has_feature(CPU_FTR_ARCH_31))
 			goto unknown_opcode;

 		prefix_r = GET_PREFIX_R(word);
 		ra = GET_PREFIX_RA(suffix);
 		rd = (suffix >> 21) & 0x1f;
 		op->reg = rd;
 		op->val = regs->gpr[rd];
 		suffixopcode = get_op(suffix);
 		prefixtype = (word >> 24) & 0x3;
 		switch (prefixtype) {
 		case 2:
 			if (prefix_r && ra)
 				return 0;
 			switch (suffixopcode) {
 			case 14:	/* paddi */
 				op->type = COMPUTE | PREFIXED;
 				op->val = mlsd_8lsd_ea(word, suffix, regs);
 				goto compute_done;
 			}
 		}
 		break;
 	case 2:		/* tdi */
 		if (rd & trap_compare(regs->gpr[ra], (short) word))
 			goto trap;
 		return 1;
 #endif
 	case 3:		/* twi */
 		if (rd & trap_compare((int)regs->gpr[ra], (short) word))
 			goto trap;
 		return 1;

 #ifdef __powerpc64__
 	case 4:
 		/*
 		 * There are very many instructions with this primary opcode
 		 * introduced in the ISA as early as v2.03. However, the ones
 		 * we currently emulate were all introduced with ISA 3.0
 		 */
 		if (!cpu_has_feature(CPU_FTR_ARCH_300))
 			goto unknown_opcode;

 		switch (word & 0x3f) {
 		case 48:	/* maddhd */
 			asm volatile(PPC_MADDHD(%0, %1, %2, %3) :
 				     "=r" (op->val) : "r" (regs->gpr[ra]),
 				     "r" (regs->gpr[rb]), "r" (regs->gpr[rc]));
 			goto compute_done;

 		case 49:	/* maddhdu */
 			asm volatile(PPC_MADDHDU(%0, %1, %2, %3) :
 				     "=r" (op->val) : "r" (regs->gpr[ra]),
 				     "r" (regs->gpr[rb]), "r" (regs->gpr[rc]));
 			goto compute_done;

 		case 51:	/* maddld */
 			asm volatile(PPC_MADDLD(%0, %1, %2, %3) :
 				     "=r" (op->val) : "r" (regs->gpr[ra]),
 				     "r" (regs->gpr[rb]), "r" (regs->gpr[rc]));
 			goto compute_done;
 		}

 		/*
 		 * There are other instructions from ISA 3.0 with the same
 		 * primary opcode which do not have emulation support yet.
 		 */
 		goto unknown_opcode;
 #endif

 	case 7:		/* mulli */
 		op->val = regs->gpr[ra] * (short) word;
 		goto compute_done;

 	case 8:		/* subfic */
 		imm = (short) word;
 		add_with_carry(regs, op, rd, ~regs->gpr[ra], imm, 1);
 		return 1;

 	case 10:	/* cmpli */
 		imm = (unsigned short) word;
 		val = regs->gpr[ra];
 #ifdef __powerpc64__
 		if ((rd & 1) == 0)
 			val = (unsigned int) val;
 #endif
 		do_cmp_unsigned(regs, op, val, imm, rd >> 2);
 		return 1;

 	case 11:	/* cmpi */
 		imm = (short) word;
 		val = regs->gpr[ra];
 #ifdef __powerpc64__
 		if ((rd & 1) == 0)
 			val = (int) val;
 #endif
 		do_cmp_signed(regs, op, val, imm, rd >> 2);
 		return 1;

 	case 12:	/* addic */
 		imm = (short) word;
 		add_with_carry(regs, op, rd, regs->gpr[ra], imm, 0);
 		return 1;

 	case 13:	/* addic. */
 		imm = (short) word;
 		add_with_carry(regs, op, rd, regs->gpr[ra], imm, 0);
 		set_cr0(regs, op);
 		return 1;

 	case 14:	/* addi */
 		imm = (short) word;
 		if (ra)
 			imm += regs->gpr[ra];
 		op->val = imm;
 		goto compute_done;

 	case 15:	/* addis */
 		imm = ((short) word) << 16;
 		if (ra)
 			imm += regs->gpr[ra];
 		op->val = imm;
 		goto compute_done;

 	case 19:
 		if (((word >> 1) & 0x1f) == 2) {
 			/* addpcis */
 			if (!cpu_has_feature(CPU_FTR_ARCH_300))
 				goto unknown_opcode;
 			imm = (short) (word & 0xffc1);	/* d0 + d2 fields */
 			imm |= (word >> 15) & 0x3e;	/* d1 field */
 			op->val = regs->nip + (imm << 16) + 4;
 			goto compute_done;
 		}
 		op->type = UNKNOWN;
 		return 0;

 	case 20:	/* rlwimi */
 		mb = (word >> 6) & 0x1f;
 		me = (word >> 1) & 0x1f;
 		val = DATA32(regs->gpr[rd]);
 		imm = MASK32(mb, me);
 		op->val = (regs->gpr[ra] & ~imm) | (ROTATE(val, rb) & imm);
 		goto logical_done;

 	case 21:	/* rlwinm */
 		mb = (word >> 6) & 0x1f;
 		me = (word >> 1) & 0x1f;
 		val = DATA32(regs->gpr[rd]);
 		op->val = ROTATE(val, rb) & MASK32(mb, me);
 		goto logical_done;

 	case 23:	/* rlwnm */
 		mb = (word >> 6) & 0x1f;
 		me = (word >> 1) & 0x1f;
 		rb = regs->gpr[rb] & 0x1f;
 		val = DATA32(regs->gpr[rd]);
 		op->val = ROTATE(val, rb) & MASK32(mb, me);
 		goto logical_done;

 	case 24:	/* ori */
 		op->val = regs->gpr[rd] | (unsigned short) word;
 		goto logical_done_nocc;

 	case 25:	/* oris */
 		imm = (unsigned short) word;
 		op->val = regs->gpr[rd] | (imm << 16);
 		goto logical_done_nocc;

 	case 26:	/* xori */
 		op->val = regs->gpr[rd] ^ (unsigned short) word;
 		goto logical_done_nocc;

 	case 27:	/* xoris */
 		imm = (unsigned short) word;
 		op->val = regs->gpr[rd] ^ (imm << 16);
 		goto logical_done_nocc;

 	case 28:	/* andi. */
 		op->val = regs->gpr[rd] & (unsigned short) word;
 		set_cr0(regs, op);
 		goto logical_done_nocc;

 	case 29:	/* andis. */
 		imm = (unsigned short) word;
 		op->val = regs->gpr[rd] & (imm << 16);
 		set_cr0(regs, op);
 		goto logical_done_nocc;

 #ifdef __powerpc64__
 	case 30:	/* rld* */
 		mb = ((word >> 6) & 0x1f) | (word & 0x20);
 		val = regs->gpr[rd];
 		if ((word & 0x10) == 0) {
 			sh = rb | ((word & 2) << 4);
 			val = ROTATE(val, sh);
 			switch ((word >> 2) & 3) {
 			case 0:		/* rldicl */
 				val &= MASK64_L(mb);
 				break;
 			case 1:		/* rldicr */
 				val &= MASK64_R(mb);
 				break;
 			case 2:		/* rldic */
 				val &= MASK64(mb, 63 - sh);
 				break;
 			case 3:		/* rldimi */
 				imm = MASK64(mb, 63 - sh);
 				val = (regs->gpr[ra] & ~imm) |
 					(val & imm);
 			}
 			op->val = val;
 			goto logical_done;
 		} else {
 			sh = regs->gpr[rb] & 0x3f;
 			val = ROTATE(val, sh);
 			switch ((word >> 1) & 7) {
 			case 0:		/* rldcl */
 				op->val = val & MASK64_L(mb);
 				goto logical_done;
 			case 1:		/* rldcr */
 				op->val = val & MASK64_R(mb);
 				goto logical_done;
 			}
 		}
 #endif
 		op->type = UNKNOWN;	/* illegal instruction */
 		return 0;

 	case 31:
 		/* isel occupies 32 minor opcodes */
 		if (((word >> 1) & 0x1f) == 15) {
 			mb = (word >> 6) & 0x1f; /* bc field */
 			val = (regs->ccr >> (31 - mb)) & 1;
 			val2 = (ra) ? regs->gpr[ra] : 0;

 			op->val = (val) ? val2 : regs->gpr[rb];
 			goto compute_done;
 		}

 		switch ((word >> 1) & 0x3ff) {
 		case 4:		/* tw */
 			if (rd == 0x1f ||
 			    (rd & trap_compare((int)regs->gpr[ra],
 					       (int)regs->gpr[rb])))
 				goto trap;
 			return 1;
 #ifdef __powerpc64__
 		case 68:	/* td */
 			if (rd & trap_compare(regs->gpr[ra], regs->gpr[rb]))
 				goto trap;
 			return 1;
 #endif
 		case 83:	/* mfmsr */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = MFMSR;
 			op->reg = rd;
 			return 0;
 		case 146:	/* mtmsr */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = MTMSR;
 			op->reg = rd;
 			op->val = 0xffffffff & ~(MSR_ME | MSR_LE);
 			return 0;
 #ifdef CONFIG_PPC64
 		case 178:	/* mtmsrd */
 			if (regs->msr & MSR_PR)
 				goto priv;
 			op->type = MTMSR;
 			op->reg = rd;
 			/* only MSR_EE and MSR_RI get changed if bit 15 set */
 			/* mtmsrd doesn't change MSR_HV, MSR_ME or MSR_LE */
 			imm = (word & 0x10000)? 0x8002: 0xefffffffffffeffeUL;
 			op->val = imm;
 			return 0;
 #endif

 		case 19:	/* mfcr */
 			imm = 0xffffffffUL;
 			if ((word >> 20) & 1) {
 				imm = 0xf0000000UL;
 				for (sh = 0; sh < 8; ++sh) {
 					if (word & (0x80000 >> sh))
 						break;
 					imm >>= 4;
 				}
 			}
 			op->val = regs->ccr & imm;
 			goto compute_done;

 		case 144:	/* mtcrf */
 			op->type = COMPUTE + SETCC;
 			imm = 0xf0000000UL;
 			val = regs->gpr[rd];
 			op->ccval = regs->ccr;
 			for (sh = 0; sh < 8; ++sh) {
 				if (word & (0x80000 >> sh))
 					op->ccval = (op->ccval & ~imm) |
 						(val & imm);
 				imm >>= 4;
 			}
 			return 1;

 		case 339:	/* mfspr */
 			spr = ((word >> 16) & 0x1f) | ((word >> 6) & 0x3e0);
 			op->type = MFSPR;
 			op->reg = rd;
 			op->spr = spr;
 			if (spr == SPRN_XER || spr == SPRN_LR ||
 			    spr == SPRN_CTR)
 				return 1;
 			return 0;

 		case 467:	/* mtspr */
 			spr = ((word >> 16) & 0x1f) | ((word >> 6) & 0x3e0);
 			op->type = MTSPR;
 			op->val = regs->gpr[rd];
 			op->spr = spr;
 			if (spr == SPRN_XER || spr == SPRN_LR ||
 			    spr == SPRN_CTR)
 				return 1;
 			return 0;

 /*
  * Compare instructions
  */
 		case 0:	/* cmp */
 			val = regs->gpr[ra];
 			val2 = regs->gpr[rb];
 #ifdef __powerpc64__
 			if ((rd & 1) == 0) {
 				/* word (32-bit) compare */
 				val = (int) val;
 				val2 = (int) val2;
 			}
 #endif
 			do_cmp_signed(regs, op, val, val2, rd >> 2);
 			return 1;

 		case 32:	/* cmpl */
 			val = regs->gpr[ra];
 			val2 = regs->gpr[rb];
 #ifdef __powerpc64__
 			if ((rd & 1) == 0) {
 				/* word (32-bit) compare */
 				val = (unsigned int) val;
 				val2 = (unsigned int) val2;
 			}
 #endif
 			do_cmp_unsigned(regs, op, val, val2, rd >> 2);
 			return 1;

 		case 508: /* cmpb */
 			do_cmpb(regs, op, regs->gpr[rd], regs->gpr[rb]);
 			goto logical_done_nocc;

 /*
  * Arithmetic instructions
  */
 		case 8:	/* subfc */
 			add_with_carry(regs, op, rd, ~regs->gpr[ra],
 				       regs->gpr[rb], 1);
 			goto arith_done;
 #ifdef __powerpc64__
 		case 9:	/* mulhdu */
 			asm("mulhdu %0,%1,%2" : "=r" (op->val) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;
 #endif
 		case 10:	/* addc */
 			add_with_carry(regs, op, rd, regs->gpr[ra],
 				       regs->gpr[rb], 0);
 			goto arith_done;

 		case 11:	/* mulhwu */
 			asm("mulhwu %0,%1,%2" : "=r" (op->val) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;

 		case 40:	/* subf */
 			op->val = regs->gpr[rb] - regs->gpr[ra];
 			goto arith_done;
 #ifdef __powerpc64__
 		case 73:	/* mulhd */
 			asm("mulhd %0,%1,%2" : "=r" (op->val) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;
 #endif
 		case 75:	/* mulhw */
 			asm("mulhw %0,%1,%2" : "=r" (op->val) :
 			    "r" (regs->gpr[ra]), "r" (regs->gpr[rb]));
 			goto arith_done;

 		case 104:	/* neg */
 			op->val = -regs->gpr[ra];
 			goto arith_done;

 		case 136:	/* subfe */
 			add_with_carry(regs, op, rd, ~regs->gpr[ra],
 				       regs->gpr[rb], regs->xer & XER_CA);
 			goto arith_done;

 		case 138:	/* adde */
 			add_with_carry(regs, op, rd, regs->gpr[ra],
 				       regs->gpr[rb], regs->xer & XER_CA);
 			goto arith_done;

 		case 200:	/* subfze */
 			add_with_carry(regs, op, rd, ~regs->gpr[ra], 0L,
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 202:	/* addze */
 			add_with_carry(regs, op, rd, regs->gpr[ra], 0L,
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 232:	/* subfme */
 			add_with_carry(regs, op, rd, ~regs->gpr[ra], -1L,
 				       regs->xer & XER_CA);
 			goto arith_done;
 #ifdef __powerpc64__
 		case 233:	/* mulld */
 			op->val = regs->gpr[ra] * regs->gpr[rb];
 			goto arith_done;
 #endif
 		case 234:	/* addme */
 			add_with_carry(regs, op, rd, regs->gpr[ra], -1L,
 				       regs->xer & XER_CA);
 			goto arith_done;

 		case 235:	/* mullw */
 			op->val = (long)(int) regs->gpr[ra] *
 				(int) regs->gpr[rb];

 			goto arith_done;
 #ifdef __powerpc64__
 		case 265:	/* modud */
 			if (!cpu_has_feature(CPU_FTR_ARCH_300))
 				goto unknown_opcode;
 			op->val = regs->gpr[ra] % regs->gpr[rb];
 			goto compute_done;
 #endif
 		case 266:	/* add */
 			op->val = regs->gpr[ra] + regs->gpr[rb];
 			goto arith_done;

 		case 267:	/* moduw */
 			if (!cpu_has_feature(CPU_FTR_ARCH_300))
 				goto unknown_opcode;
 			op->val = (unsigned int) regs->gpr[ra] %
 				(unsigned int) regs->gpr[rb];
 			goto compute_done;
 #ifdef __powerpc64__
 		case 457:	/* divdu */
 			op->val = regs->gpr[ra] / regs->gpr[rb];
 			goto arith_done;
 #endif
 		case 459:	/* divwu */
 			op->val = (unsigned int) regs->gpr[ra] /
 				(unsigned int) r

Provide a response strictly in the following format:

The code statements that lead to the bug are:
<text>
<text>
